namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
    public string ImageUrl { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Location { get; set; } = "";
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = "";
    public int InstructorId { get; set; }
    public string InstructorName { get; set; } = "";
    public bool IsFeatured { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
}

public class EnrollmentRequestModel
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequestModel> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and language studies." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and their impact on the present." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers in top-tier conferences and holds three patents in natural language processing.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Mathematics", Bio = "Dr. Martinez focuses on applied mathematics and numerical analysis. He previously worked at NASA's Jet Propulsion Laboratory on trajectory optimization.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Prof. Sarah Williams", Title = "Professor of English", Bio = "Prof. Williams is an award-winning author and literary critic specializing in contemporary American fiction and creative writing.", Email = "swilliams@university.edu" },
            new() { Id = 4, Name = "Dr. James Park", Title = "Associate Professor of Physics", Bio = "Dr. Park's research centers on quantum computing and condensed matter physics. He leads the university's Quantum Information Lab.", Email = "jpark@university.edu" },
            new() { Id = 5, Name = "Dr. Maria Johnson", Title = "Professor of History", Bio = "Dr. Johnson is a specialist in modern European history with a focus on the social impacts of industrialization. She has authored three books on 19th-century labor movements.", Email = "mjohnson@university.edu" },
            new() { Id = 6, Name = "Dr. David Lee", Title = "Assistant Professor of Computer Science", Bio = "Dr. Lee's research interests include distributed systems, cloud computing, and software engineering. He brings industry experience from working at major tech companies.", Email = "dlee@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, data structures, and object-oriented programming. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 1, InstructorName = "Dr. Alice Chen", IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "In-depth study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Includes complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Engineering Bldg 105", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 6, InstructorName = "Dr. David Lee", IsFeatured = true, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS 450", Title = "Machine Learning", Description = "Survey of machine learning methods including supervised learning, unsupervised learning, and reinforcement learning. Hands-on projects using real-world datasets.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Science Hall 305", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 1, InstructorName = "Dr. Alice Chen", IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 38 },
            new() { Id = 4, Code = "MATH 201", Title = "Calculus II", Description = "Continuation of single-variable calculus covering techniques of integration, sequences, series, and an introduction to multivariable calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Math Bldg 102", DepartmentId = 2, DepartmentName = "Mathematics", InstructorId = 2, InstructorName = "Dr. Robert Martinez", IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 62 },
            new() { Id = 5, Code = "MATH 340", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to data science and engineering.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Bldg 205", DepartmentId = 2, DepartmentName = "Mathematics", InstructorId = 2, InstructorName = "Dr. Robert Martinez", IsFeatured = true, MaxEnrollment = 50, CurrentEnrollment = 44 },
            new() { Id = 6, Code = "ENG 110", Title = "College Writing", Description = "Develop skills in academic writing, critical reading, and argumentation. Focus on clear, well-organized essays with proper citation.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Humanities 301", DepartmentId = 3, DepartmentName = "English", InstructorId = 3, InstructorName = "Prof. Sarah Williams", IsFeatured = false, MaxEnrollment = 25, CurrentEnrollment = 22 },
