    <div class="row">
        <div class="col-lg-8">
            <h1>@_course.Code — @_course.Title</h1>
            <span class="badge bg-primary mb-3">@_course.DepartmentName</span>

            <h4 class="mt-4">Description</h4>
            <p>@_course.Description</p>

            <h4 class="mt-4">Instructor</h4>
