@page "/"
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">University Course Catalog</h1>
    <p class="lead text-muted">Browse courses, explore departments, and request enrollment — all in one place.</p>
    <a href="/catalog" class="btn btn-primary btn-lg">Browse All Courses</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in _featuredCourses)
        {
            <div class="col">
                <FeaturedCourseCard Course="course" />
            </div>
        }
    </div>
</section>

<section>
    <h2 class="mb-3">Departments</h2>
    <div class="row row-cols-2 row-cols-md-3 row-cols-lg-5 g-3">
        @foreach (var dept in _departments)
        {
            <div class="col">
                <DepartmentLinkCard Department="dept" />
            </div>
        }
    </div>
</section>

@code {
    private List<Course> _featuredCourses = new();
    private List<Department> _departments = new();

    protected override void OnInitialized()
    {
        _featuredCourses = CatalogService.GetFeaturedCourses();
        _departments = CatalogService.GetDepartments();
    }
}

toolArgs.file_text:
@page "/courses/{Id:int}"
@inject CatalogService CatalogService

@if (_course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <div class="alert alert-warning">Course not found. <a href="/catalog">Return to catalog</a>.</div>
}
else
{
    <PageTitle>@_course.Code — @_course.Title</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/catalog">Catalog</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@_course.Code — @_course.Title</h1>
            <span class="badge bg-primary mb-3">@_course.DepartmentName</span>

            <h4 class="mt-4">Description</h4>
            <p>@_course.Description</p>

            <h4 class="mt-4">Instructor</h4>
            @if (_instructor is not null)
            {
                <InstructorBio Instructor="_instructor" />
            }
        </div>

        <div class="col-lg-4">
            <div class="card shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">Course Details</h5>
                    <dl>
                        <dt>Credits</dt>
                        <dd>@_course.Credits</dd>

                        <dt>Schedule</dt>
                        <dd>@_course.Schedule</dd>

                        <dt>Location</dt>
                        <dd>@_course.Location</dd>

                        <dt>Enrollment</dt>
                        <dd>
                            @_course.CurrentEnrollment / @_course.MaxEnrollment
                            @if (_course.MaxEnrollment - _course.CurrentEnrollment > 0)
                            {
                                <span class="badge bg-success ms-1">
                                    @(_course.MaxEnrollment - _course.CurrentEnrollment) seats open
                                </span>
                            }
                            else
                            {
                                <span class="badge bg-danger ms-1">Full</span>
                            }
                        </dd>
                    </dl>

                    <a href="/enroll?courseId=@_course.Id" class="btn btn-primary w-100">Request Enrollment</a>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? _course;
    private Instructor? _instructor;

    protected override void OnInitialized()
    {
        _course = CatalogService.GetCourse(Id);
        if (_course is not null)
            _instructor = CatalogService.GetInstructor(_course.InstructorId);
    }
}

@page "/enroll"
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for
            <strong>@_selectedCourseTitle</strong> has been received. You will be notified by email once processed.</p>
        <hr>
        <a href="/catalog" class="btn btn-outline-success">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <DataAnnotationsValidator />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" required />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId"
                               placeholder="e.g. S12345678" required />
                </div>

                <div class="mb-3">
                    <label for="courseSelect" class="form-label">Course</label>
                    <InputSelect id="courseSelect" class="form-select" @bind-Value="_model.CourseId">
                        <option value="0" disabled>— Select a course —</option>
                        @foreach (var course in _courses)
                        {
                            <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                        }
                    </InputSelect>
                </div>

                <button type="submit" class="btn btn-primary" disabled="@(_model.CourseId == 0)">
                    Submit Request
                </button>
                <a href="/catalog" class="btn btn-outline-secondary ms-2">Cancel</a>
            </EditForm>
        </div>

        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h6 class="card-title">How It Works</h6>
                    <ol class="small mb-0">
                        <li>Enter your name and student ID.</li>
                        <li>Select a course from the dropdown.</li>
                        <li>Submit your request.</li>
                        <li>You'll receive a confirmation email within 1–2 business days.</li>
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private EnrollmentRequestModel _model = new();
    private List<Course> _courses = new();
    private bool _submitted;
    private string _selectedCourseTitle = "";

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();
        if (CourseId.HasValue)
            _model.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(_model.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown";
        CatalogService.SubmitEnrollmentRequest(_model);
        _submitted = true;
    }
}

